-- C-04 fiscal configuration. Financial document engines are unchanged.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema tax_catalog_private;revoke all on schema tax_catalog_private from public,anon,authenticated,service_role;grant usage on schema tax_catalog_private to authenticated;
create function tax_catalog_private.meta(k text)returns table(t text,pk text,fields text[],label text)language sql immutable set search_path=pg_catalog as $$select c.t,c.pk,c.fields,c.label from(values
 ('tax-agencies','tax_agencies','tax_agency_id',array['agency_name','country_id','tax_id'],'agency_name'),
 ('tax-types','tax_types','tax_type_id',array['country_id','type_name','applies_to','is_indirect_tax','asset_account_id','liability_account_id'],'type_name'),
 ('tax-codes','tax_codes','tax_code_id',array['code_name','country_id','tax_agency_id','tax_type_id','rate_percentage','is_withholding','is_purchase_creditable','is_import_tax','withholding_calculation_base','withholding_application_moment'],'code_name'),
 ('tax-groups','tax_groups','tax_group_id',array['group_code','group_name','subsidiary_id'],'group_name'))c(k,t,pk,fields,label)where c.k=$1$$;
create function tax_catalog_private.identity()returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin if not exists(select 1 from public.users u join public.user_roles ur using(user_id)where u.user_id=public.app_user_id()and u.is_active and ur.role_id=public.app_active_role_id())then raise exception using errcode='42501',message='Seleccione usuario y rol activos autorizados.';end if;return sid;end$$;
create function tax_catalog_private.country()returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare cid bigint;begin select country_id into cid from public.subsidiaries where subsidiary_id=tax_catalog_private.identity()and is_active;if cid is null then raise exception using errcode='42501',message='Seleccione una subsidiaria activa con país configurado.';end if;return cid;end$$;
create function tax_catalog_private.allowed(k text,a text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform tax_catalog_private.identity();if not exists(select 1 from tax_catalog_private.meta(k))or a not in('view','create','edit','delete')then return false;end if;if a='view'then return asset_posting_private.allowed('configuration:'||k,'view');end if;return exists(select 1 from public.role_access_matrix m where m.role_id=public.app_active_role_id()and m.resource_key='configuration:'||k and case a when'create'then m.can_create when'edit'then m.can_edit else m.can_delete end);exception when insufficient_privilege then return false;end$$;
create function tax_catalog_private.access(k text,a text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=tax_catalog_private.identity();begin if not tax_catalog_private.allowed(k,a)then raise exception using errcode='42501',message='Requiere permiso explícito para esta operación fiscal.';end if;perform tax_catalog_private.country();return sid;end$$;
create function tax_catalog_private.read_allowed(k text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform tax_catalog_private.identity();return tax_catalog_private.allowed(k,'view')or exists(select 1 from public.role_access_matrix m where m.role_id=public.app_active_role_id()and(m.can_view or m.can_create or m.can_edit)and m.resource_key in('entities:customers','entities:suppliers','inventory:products','accounting:journals','accounting:payment-requests','treasury:payment-requests','purchasing:supplier-invoices','purchasing:purchase-orders','purchasing:supplier-payments','sales:invoices','sales:sales-orders','sales:credit-notes','sales:debit-notes','sales:customer-payments'));exception when insufficient_privilege then return false;end$$;
create function tax_catalog_private.scope_ids(k text,id bigint)returns bigint[]language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select coalesce(array_agg(distinct sid),'{}'::bigint[])from(
 select subsidiary_id sid from public.tax_code_subsidiaries where k='tax-codes'and tax_code_id=$2 union all
 select subsidiary_id from public.tax_agency_subsidiaries where k='tax-agencies'and tax_agency_id=$2 union all
 select s.subsidiary_id from public.tax_codes c join public.tax_code_subsidiaries s using(tax_code_id)where k='tax-types'and c.tax_type_id=$2 union all
 select subsidiary_id from public.tax_groups where k='tax-groups'and tax_group_id=$2)q$$;
create function tax_catalog_private.scope_writable(k text,id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select not exists(select 1 from unnest(tax_catalog_private.scope_ids(k,id))s where not exists(select 1 from public.user_subsidiaries us join public.subsidiaries c using(subsidiary_id)where us.user_id=public.app_user_id()and us.subsidiary_id=s and c.country_id=tax_catalog_private.country()))$$;
create function tax_catalog_private.visible(k text,id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=tax_catalog_private.identity();cid bigint:=tax_catalog_private.country();begin if not tax_catalog_private.read_allowed(k)then return false;end if;
 if k='tax-codes'then return exists(select 1 from public.tax_codes c join public.tax_code_subsidiaries s using(tax_code_id)where c.tax_code_id=$2 and c.country_id=cid and s.subsidiary_id=sid);
 elsif k='tax-agencies'then return exists(select 1 from public.tax_agencies a where a.tax_agency_id=$2 and a.country_id=cid and(exists(select 1 from public.tax_agency_subsidiaries s where s.tax_agency_id=a.tax_agency_id and s.subsidiary_id=sid)or not exists(select 1 from public.tax_agency_subsidiaries s where s.tax_agency_id=a.tax_agency_id)));
 elsif k='tax-types'then return exists(select 1 from public.tax_types where tax_type_id=$2 and country_id=cid);
 elsif k='tax-groups'then return exists(select 1 from public.tax_groups where tax_group_id=$2 and subsidiary_id=sid);end if;return false;exception when insufficient_privilege then return false;end$$;
create function tax_catalog_private.used(t text,id bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare fk record;found boolean;begin for fk in select n.nspname,c.relname,a.attname,cardinality(co.conkey)len from pg_constraint co join pg_class c on c.oid=co.conrelid join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum=co.conkey[1]where co.contype='f'and co.confrelid=to_regclass('public.'||t)and c.relname not in('tax_code_subsidiaries','tax_agency_subsidiaries')loop if fk.len<>1 then return true;end if;execute format('select exists(select 1 from %I.%I where %I=$1)',fk.nspname,fk.relname,fk.attname)into found using id;if found then return true;end if;end loop;return false;end$$;
create function tax_catalog_private.fingerprint(k text,id bigint)returns text language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin select *into c from tax_catalog_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;return md5(jsonb_build_array(r,(select array_agg(s order by s)from unnest(tax_catalog_private.scope_ids(k,id))s))::text);end$$;
create function tax_catalog_private.account(id bigint,cat text,sids bigint[])returns void language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if id is null then return;end if;if not exists(select 1 from public.chart_accounts a where a.account_id=$1 and a.category=cat and a.accepts_entries and not a.is_inactive)or exists(select 1 from unnest(sids)s where not exists(select 1 from public.account_subsidiaries x where x.account_id=$1 and x.subsidiary_id=s and x.is_active))then raise exception using errcode='42501',message='Cuenta fiscal no disponible para las subsidiarias.';end if;end$$;
create function tax_catalog_private.dto(k text,id bigint)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin select *into c from tax_catalog_private.meta(k);execute format('select to_jsonb(x)from public.%I x where %I=$1',c.t,c.pk)into r using id;return r||jsonb_build_object('_revision',tax_catalog_private.fingerprint(k,id),'_actions',jsonb_build_object('canEdit',tax_catalog_private.allowed(k,'edit')and tax_catalog_private.scope_writable(k,id),'canDelete',tax_catalog_private.allowed(k,'delete')and tax_catalog_private.scope_writable(k,id)and not tax_catalog_private.used(c.t,id)))||case when k in('tax-codes','tax-agencies')then jsonb_build_object('subsidiary_ids',coalesce((select jsonb_agg(s order by s)from unnest(tax_catalog_private.scope_ids(k,id))s where exists(select 1 from public.user_subsidiaries us where us.user_id=public.app_user_id()and us.subsidiary_id=s)),'[]'::jsonb))else'{}'::jsonb end||case when k='tax-codes'then jsonb_build_object('tax_type_applies_to',(select applies_to from public.tax_types where tax_type_id=(r->>'tax_type_id')::bigint))else'{}'::jsonb end;end$$;
create function public.tax_catalog_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin perform tax_catalog_private.access(p_catalog,'view');select *into c from tax_catalog_private.meta(p_catalog);execute format('select coalesce(jsonb_agg(tax_catalog_private.dto($1,%I)order by %I),''[]''::jsonb)from public.%I where tax_catalog_private.visible($1,%I)',c.pk,c.pk,c.t,c.pk)into r using p_catalog;return r;end$$;
create function public.tax_catalog_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=tax_catalog_private.access(p_catalog,'view');cid bigint:=tax_catalog_private.country();begin return jsonb_build_object('canView',true,'canCreate',tax_catalog_private.allowed(p_catalog,'create'),'canEdit',tax_catalog_private.allowed(p_catalog,'edit'),'canDelete',tax_catalog_private.allowed(p_catalog,'delete'),'references',jsonb_build_object(
 'core/countries',coalesce((select jsonb_agg(to_jsonb(c))from public.countries c where country_id=cid),'[]'::jsonb),
 'organization/subsidiaries',coalesce((select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name,'country_id',s.country_id))from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where us.user_id=public.app_user_id()and s.country_id=cid and s.is_active and(p_catalog<>'tax-groups'or s.subsidiary_id=sid)),'[]'::jsonb),
 'configuration/tax-agencies',coalesce((select jsonb_agg(to_jsonb(a))from public.tax_agencies a where tax_catalog_private.visible('tax-agencies',a.tax_agency_id)),'[]'::jsonb),
 'configuration/tax-types',coalesce((select jsonb_agg(to_jsonb(t))from public.tax_types t where t.country_id=cid),'[]'::jsonb),
 'accounting/chart-accounts',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('subsidiary_ids',(select jsonb_agg(x.subsidiary_id)from public.account_subsidiaries x join public.user_subsidiaries us using(subsidiary_id)where x.account_id=a.account_id and x.is_active and us.user_id=public.app_user_id())))from public.chart_accounts a where a.category in('Activo','Pasivo')and a.accepts_entries and not a.is_inactive and exists(select 1 from public.account_subsidiaries x where x.account_id=a.account_id and x.subsidiary_id=sid and x.is_active)),'[]'::jsonb)));end$$;

create function public.save_tax_catalog(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;sid bigint;cid bigint;oldrow jsonb;data jsonb;typed jsonb;r jsonb;ids bigint[];oldids bigint[];target bigint;key text;cols text;vals text;sets text;pid bigint;used boolean;tt public.tax_types;begin
 sid:=tax_catalog_private.access(p_catalog,case when p_id is null then'create'else'edit'end);cid:=tax_catalog_private.country();select *into c from tax_catalog_private.meta(p_catalog);
 if p_id<=0 or jsonb_typeof(p_payload)is distinct from'object'or pg_column_size(p_payload)>32000 or exists(select 1 from jsonb_object_keys(p_payload)x where not x=any(c.fields||array['subsidiary_ids','_revision']))then raise exception using errcode='22023',message='Campos fiscales inválidos.';end if;
 perform pg_advisory_xact_lock(793144,1);
 if p_id is not null then execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into oldrow using p_id;
  if oldrow is null or not tax_catalog_private.visible(p_catalog,p_id)or not tax_catalog_private.scope_writable(p_catalog,p_id)then raise exception using errcode='42501',message='Registro fiscal no disponible para mantenimiento.';end if;
  if p_payload->>'_revision'is distinct from tax_catalog_private.fingerprint(p_catalog,p_id)then raise exception using errcode='55000',message='El catálogo cambió; consúltelo nuevamente.';end if;
 end if;
 data:=coalesce(oldrow,case p_catalog when'tax-types'then'{"is_indirect_tax":false}'::jsonb when'tax-codes'then'{"is_withholding":false,"is_purchase_creditable":true,"is_import_tax":false}'::jsonb else'{}'::jsonb end)||(p_payload-'subsidiary_ids'-'_revision');
 foreach key in array c.fields loop if data->>key=''then data:=jsonb_set(data,array[key],'null');end if;if key like'is_%'and data?key and jsonb_typeof(data->key)is distinct from'boolean'then raise exception using errcode='22023',message='Las opciones fiscales deben ser booleanas.';end if;end loop;
 execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',c.t)into typed using data;data:=typed;
 if nullif(trim(data->>c.label),'')is null or length(data->>c.label)>250 then raise exception using errcode='22023',message='Indique un nombre fiscal de hasta 250 caracteres.';end if;
 if p_catalog='tax-groups'then if(data->>'subsidiary_id')::bigint is distinct from sid or nullif(trim(data->>'group_code'),'')is null or length(data->>'group_code')>80 then raise exception using errcode='42501',message='Grupo fiscal no disponible para la subsidiaria.';end if;ids:=array[sid];
 else if(data->>'country_id')::bigint is distinct from cid then raise exception using errcode='42501',message='El país debe corresponder a la subsidiaria activa.';end if;end if;
 if p_catalog in('tax-codes','tax-agencies')then
  if jsonb_typeof(p_payload->'subsidiary_ids')is distinct from'array'or jsonb_array_length(p_payload->'subsidiary_ids')not between 1 and 200 then raise exception using errcode='22023',message='Seleccione las subsidiarias autorizadas donde aplica.';end if;
  for r in select value from jsonb_array_elements(p_payload->'subsidiary_ids')loop if jsonb_typeof(r)not in('number','string')or(r#>>'{}')!~'^[1-9][0-9]{0,15}$'then raise exception using errcode='22023',message='Subsidiaria inválida.';end if;end loop;
  select array_agg((value#>>'{}')::bigint)into ids from jsonb_array_elements(p_payload->'subsidiary_ids');
  if cardinality(ids)<>(select count(distinct x)from unnest(ids)x)or not sid=any(ids)or exists(select 1 from unnest(ids)x where not exists(select 1 from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where s.subsidiary_id=x and s.country_id=cid and s.is_active and us.user_id=public.app_user_id()))then raise exception using errcode='42501',message='Las subsidiarias deben estar autorizadas y pertenecer al país activo.';end if;
 end if;
 if p_catalog='tax-types'then
  if coalesce(data->>'applies_to','')not in('Compras','Ventas','Ambos')then raise exception using errcode='22023',message='Seleccione el ámbito del impuesto.';end if;
  ids:=array[sid]||coalesce(tax_catalog_private.scope_ids(p_catalog,p_id),'{}'::bigint[]);perform tax_catalog_private.account((data->>'asset_account_id')::bigint,'Activo',ids);perform tax_catalog_private.account((data->>'liability_account_id')::bigint,'Pasivo',ids);
 elsif p_catalog='tax-codes'then
  if not asset_posting_private.finite((data->>'rate_percentage')::numeric)or(data->>'rate_percentage')::numeric not between 0 and 100 then raise exception using errcode='22023',message='El porcentaje debe ser finito entre cero y cien.';end if;
  select *into tt from public.tax_types where tax_type_id=(data->>'tax_type_id')::bigint and country_id=cid;
  if not found or not exists(select 1 from public.tax_agencies where tax_agency_id=(data->>'tax_agency_id')::bigint and country_id=cid)or exists(select 1 from unnest(ids)x where not exists(select 1 from public.tax_agency_subsidiaries s where s.tax_agency_id=(data->>'tax_agency_id')::bigint and s.subsidiary_id=x))then raise exception using errcode='42501',message='Tipo, agencia o asignación fiscal no disponible.';end if;
  perform tax_catalog_private.account(tt.asset_account_id,'Activo',ids);perform tax_catalog_private.account(tt.liability_account_id,'Pasivo',ids);
  if(data->>'is_withholding')::boolean then if coalesce(data->>'withholding_calculation_base','')not in('Subtotal antes de impuestos','Importe de impuestos','Total de la factura con impuestos')or coalesce(data->>'withholding_application_moment','')not in('Al registrar la factura','Al aplicar el pago')then raise exception using errcode='22023',message='Configure base y momento de la retención.';end if;else data:=data||'{"withholding_calculation_base":null,"withholding_application_moment":null}'::jsonb;end if;
 end if;
 if p_id is not null then used:=tax_catalog_private.used(c.t,p_id);if used then foreach key in array c.fields loop if key<>c.label and data->key is distinct from oldrow->key then raise exception using errcode='55000',message='La configuración fiscal utilizada conserva sus condiciones. Cree una nueva versión.';end if;end loop;
  oldids:=tax_catalog_private.scope_ids(p_catalog,p_id);if p_catalog in('tax-codes','tax-agencies')and not oldids<@ids then raise exception using errcode='55000',message='No quite asignaciones de una configuración fiscal utilizada.';end if;end if;end if;
 select string_agg(format('%I',x),','),string_agg(format('r.%I',x),','),string_agg(format('%I=r.%I',x,x),',')into cols,vals,sets from unnest(c.fields)x;
 if p_id is null then execute format('insert into public.%I(%s)select %s from jsonb_populate_record(null::public.%I,$1)r returning %I',c.t,cols,vals,c.t,c.pk)into pid using data;
 else pid:=p_id;execute format('update public.%I x set %s from jsonb_populate_record(null::public.%I,$1)r where x.%I=$2',c.t,sets,c.t,c.pk)using data,pid;end if;
 if p_catalog='tax-codes'then delete from public.tax_code_subsidiaries where tax_code_id=pid;insert into public.tax_code_subsidiaries(tax_code_id,subsidiary_id)select pid,x from unnest(ids)x;
 elsif p_catalog='tax-agencies'then delete from public.tax_agency_subsidiaries where tax_agency_id=pid;insert into public.tax_agency_subsidiaries(tax_agency_id,subsidiary_id)select pid,x from unnest(ids)x;end if;
 return tax_catalog_private.dto(p_catalog,pid);end$$;
create function public.delete_tax_catalog(p_catalog text,p_id bigint,p_revision text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;r jsonb;begin perform tax_catalog_private.access(p_catalog,'delete');perform pg_advisory_xact_lock(793144,1);select *into c from tax_catalog_private.meta(p_catalog);if p_id is null or p_id<=0 then raise exception using errcode='22023',message='Identificador fiscal inválido.';end if;execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into r using p_id;
 if r is null or not tax_catalog_private.visible(p_catalog,p_id)or not tax_catalog_private.scope_writable(p_catalog,p_id)then raise exception using errcode='42501',message='Registro fiscal no disponible.';end if;if p_revision is distinct from tax_catalog_private.fingerprint(p_catalog,p_id)or tax_catalog_private.used(c.t,p_id)then raise exception using errcode='55000',message='El registro cambió o está utilizado.';end if;execute format('delete from public.%I where %I=$1',c.t,c.pk)using p_id;return true;end$$;

do $$declare t text;k text;p record;c record;pred text;begin foreach t in array array['tax_agencies','tax_types','tax_codes','tax_groups','tax_code_subsidiaries','tax_agency_subsidiaries']loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);for c in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',c.column_name,c.column_name,c.column_name,c.column_name,t);end loop;
 k:=replace(t,'_','-');pred:=case t when'tax_code_subsidiaries'then'tax_catalog_private.visible(''tax-codes'',tax_code_id)and subsidiary_id=public.active_subsidiary_id()'when'tax_agency_subsidiaries'then'tax_catalog_private.visible(''tax-agencies'',tax_agency_id)and subsidiary_id=public.active_subsidiary_id()'else format('tax_catalog_private.visible(%L,%I)',k,(select pk from tax_catalog_private.meta(k)))end;
 execute format('create policy fiscal_catalog_read on public.%I for select to authenticated using(%s)',t,pred);execute format('grant select on public.%I to authenticated',t);
end loop;end$$;
revoke all on all functions in schema tax_catalog_private from public,anon,authenticated,service_role;grant execute on function tax_catalog_private.visible(text,bigint)to authenticated;
revoke all on function public.tax_catalog_list(text),public.tax_catalog_options(text),public.save_tax_catalog(text,jsonb,bigint),public.delete_tax_catalog(text,bigint,text)from public,anon,authenticated,service_role;
grant execute on function public.tax_catalog_list(text),public.tax_catalog_options(text),public.save_tax_catalog(text,jsonb,bigint),public.delete_tax_catalog(text,bigint,text)to authenticated;
notify pgrst,'reload schema';
